import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Common use cases","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/use-cases.md","filePath":"en/guides/use-cases.md"}'),i={name:"en/guides/use-cases.md"};function o(r,e,l,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/use-cases.md for this page in Markdown format</div><h1 id="common-use-cases" tabindex="-1">Common use cases <a class="header-anchor" href="#common-use-cases" aria-label="Permalink to &quot;Common use cases&quot;">​</a></h1><p>This page collects typical Kimi Code CLI scenarios along with ready-to-use prompt examples — copy them as-is or adapt them to your needs.</p><h2 id="understanding-an-unfamiliar-project" tabindex="-1">Understanding an unfamiliar project <a class="header-anchor" href="#understanding-an-unfamiliar-project" aria-label="Permalink to &quot;Understanding an unfamiliar project&quot;">​</a></h2><p>When taking over an unfamiliar repository, a good first step is to use <code>kimi --plan</code> or press <code>Shift-Tab</code> to enter Plan mode, so the agent outputs a research plan before touching anything:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Give me an overview of this repository&#39;s architecture. Specifically:</span></span>
<span class="line"><span>1. Where is the entry point and what happens at startup?</span></span>
<span class="line"><span>2. How do the main modules depend on each other?</span></span>
<span class="line"><span>3. How are configuration and data loaded?</span></span>
<span class="line"><span>Finally, draw a simple module dependency diagram.</span></span></code></pre></div><p>You can also focus on a specific question:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How does the event loop in src/runtime work? Where do events originate, and what consumes them?</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>How is &quot;permission approval&quot; implemented in this project? Which files are involved, and what are the key types?</span></span></code></pre></div><p>For large-scale investigations, you can have the main agent dispatch <strong>sub-agents</strong> to handle sub-tasks in parallel. See <a href="./../customization/agents.html">Agents and sub-agents</a>.</p><h2 id="implementing-a-new-feature" tabindex="-1">Implementing a new feature <a class="header-anchor" href="#implementing-a-new-feature" aria-label="Permalink to &quot;Implementing a new feature&quot;">​</a></h2><p>Describe the requirement and acceptance criteria clearly. For complex changes, use Plan mode to confirm the approach before execution:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a retry utility under src/utils:</span></span>
<span class="line"><span>- Signature: retry&lt;T&gt;(fn: () =&gt; Promise&lt;T&gt;, options): Promise&lt;T&gt;</span></span>
<span class="line"><span>- Options: maxAttempts, initialDelayMs, backoffFactor</span></span>
<span class="line"><span>- On failure, throw the error from the last attempt</span></span>
<span class="line"><span>- Add a unit test suite covering: success on first try, success after retries, and all attempts failing</span></span></code></pre></div><p>If the result isn&#39;t right, just describe what you want changed — no need to edit manually:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The backoff calculation used a fixed value. I&#39;d like to add some jitter to avoid the thundering-herd effect. Update the implementation and the tests.</span></span></code></pre></div><h2 id="fixing-a-bug" tabindex="-1">Fixing a bug <a class="header-anchor" href="#fixing-a-bug" aria-label="Permalink to &quot;Fixing a bug&quot;">​</a></h2><p>Give the symptom, reproduction steps, and expected behavior all at once to avoid back-and-forth clarification:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Running npm test occasionally produces this error:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  TypeError: Cannot read properties of undefined (reading &#39;id&#39;)</span></span>
<span class="line"><span>      at SessionStore.update (src/session/store.ts:142:18)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>It only appears in test cases that concurrently trigger multiple updates. Please locate the cause and fix it, then run the full test suite to confirm.</span></span></code></pre></div><p>When the root cause is unclear, ask the agent to investigate before making changes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User feedback: after a successful login, the first page refresh sends you back to the login page; a second refresh works fine. Please find the most likely causes first and list the most suspicious locations. I&#39;ll confirm the direction before you start making changes.</span></span></code></pre></div><p>For purely mechanical tasks, you can let the agent run freely:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run the test suite, fix every failing test case, then run it again to confirm everything is green.</span></span></code></pre></div><h2 id="writing-tests-and-refactoring" tabindex="-1">Writing tests and refactoring <a class="header-anchor" href="#writing-tests-and-refactoring" aria-label="Permalink to &quot;Writing tests and refactoring&quot;">​</a></h2><p>Tasks with clear boundaries and explicit acceptance criteria are particularly well-suited for the agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/parser/markdown.ts currently has almost no tests. Please add a unit test suite covering: normal paragraphs, nested lists, code blocks, tables, blockquotes, and mixed content. Follow the testing style already used in the project.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extract the repeated &quot;read body → validate → log → respond&quot; pattern in src/handlers into a middleware. Run the tests afterwards to make sure existing behavior is unchanged.</span></span></code></pre></div><p>For multi-file refactors, use Plan mode first to confirm the approach. You can also <code>/fork</code> the session into an experimental branch and switch to it from <code>/sessions</code> — forking itself never disrupts the original session, so you can simply switch back if you don&#39;t like the result.</p><h2 id="one-off-scripts-and-automation" tabindex="-1">One-off scripts and automation <a class="header-anchor" href="#one-off-scripts-and-automation" aria-label="Permalink to &quot;One-off scripts and automation&quot;">​</a></h2><p>Batch file edits, statistics collection, and research comparisons can all be done with a single prompt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Change all var declarations in .js files under src to const or let, preferring const where possible. Run lint once you&#39;re done to confirm.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Analyze the access logs in logs/ from the past 7 days. For each API path, compute the call count, p50, and p99 response times, and output the results as a Markdown table.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Research the main dependency injection options for TypeScript (tsyringe, inversify, awilix). Compare them across three dimensions: API style, decorator requirements, and runtime overhead. Give me a recommendation that fits on one page.</span></span></code></pre></div><p>For batch tasks you know are safe, use <code>--yolo</code> or <code>/yolo</code> to skip approval prompts, or add pre-approved allowlist rules for specific tools in <a href="./../configuration/config-files.html#permission">Configuration files</a>.</p><h2 id="scheduled-tasks-and-reminders" tabindex="-1">Scheduled tasks and reminders <a class="header-anchor" href="#scheduled-tasks-and-reminders" aria-label="Permalink to &quot;Scheduled tasks and reminders&quot;">​</a></h2><p>Inside an interactive session, you can ask the agent to set one-time reminders or recurring tasks. The agent generates a cron expression in your local timezone and re-injects the prompt into the same session when it fires:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Remind me at 2:30 PM to check the deployment.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Every weekday at 9 AM, summarize recent CI failures for me.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check the production health endpoint every hour and let me know if anything looks wrong.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Come back in about 10 minutes and check whether the build has finished.</span></span></code></pre></div><p>Scheduled tasks are bound to their session — closing the terminal is fine, and they are reloaded and continue firing when you resume the same session with <code>kimi --session</code>. They are not carried into brand-new sessions. Recurring tasks expire after 7 days — the agent receives a <code>stale</code> signal on the final trigger and decides whether to stop or renew based on your original instructions.</p><p>To see what tasks are currently pending, just ask the agent (it calls the read-only <code>CronList</code> tool). To cancel a task, tell the agent to remove it or reference its 8-character ID. For the full tool reference, see <a href="./../reference/tools.html#scheduled-tasks">Scheduled tasks</a>. The global kill switch is <code>KIMI_DISABLE_CRON=1</code>.</p><h2 id="generating-and-maintaining-documentation" tabindex="-1">Generating and maintaining documentation <a class="header-anchor" href="#generating-and-maintaining-documentation" aria-label="Permalink to &quot;Generating and maintaining documentation&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I just changed the interface signature in src/auth/login.ts. Please update the corresponding JSDoc, the example code in README, and any paragraphs in docs/en/guides that mention this interface.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For every public function under src/api that is missing a docstring, add a documentation comment following the style of the existing ones.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Based on the command implementations in src/cli, generate a draft command reference listing each subcommand, its arguments, and default values. Put it in docs/en/reference for me to review later.</span></span></code></pre></div><p>When you need a record or a retrospective, use <code>kimi export &lt;sessionId&gt;</code> to package the session as a ZIP, or use <code>/export-md</code> inside the TUI to export a readable Markdown transcript.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../customization/agents.html">Agents and sub-agents</a> — how to have the agent dispatch sub-tasks for parallel execution</li><li><a href="./../customization/hooks.html">Hooks</a> — trigger local scripts at task-completion and other lifecycle points</li><li><a href="./../reference/tools.html">Built-in tools</a> — full reference of all tools the agent can call</li></ul>`,48)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
